              code: "function jparse(v) {\n  if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } }\n  return v === undefined ? null : v;\n}\nfunction isObj(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }\nfunction uniq(a) { var s = {}, o = []; a.forEach(function (x) { if (!s[x]) { s[x] = 1; o.push(x); } }); return o; }\n\n// \u2500\u2500 SHA-256\uFF08\u7D14 JS\uFF1Btoken \u53EA\u5B58\u96DC\u6E4A\uFF09\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction innerOf(r) {\n  if (!r) return null;\n  if (Array.isArray(r.records) || r.record) return r;       // \u5DF2\u7D93\u662F KBDB \u7684\u672C\u9AD4\n  if (r.success === false) return null;\n  return jparse(r.data);                                    // recipe \u7684\u5916\u6BBC {success, status, data}\n}\nfunction rowsOf(r) {\n  var d = innerOf(r);\n  if (!d) return [];\n  var a = Array.isArray(d.records) ? d.records : (d.record ? [d.record] : []);\n  return a.map(function (x) { return { rid: x.record_id, v: isObj(x.values) ? x.values : {} }; });\n}\n// \u8B80\u6EFF\u4E00\u6574\u9801\uFF1D\u53EF\u80FD\u9084\u6709\u66F4\u591A\uFF08KBDB \u7684 total \u5728\u9801\u6EFF\u6642\u53EA\u7D66\u4E0B\u754C\uFF09\u2014\u2014\u547C\u53EB\u7AEF\u64DA\u6B64\u6C7A\u5B9A\u8981\u4E0D\u8981\u8AAA\u300C\u9019\u88E1\u53EA\u770B\u4E86\u6700\u8FD1 N \u7B46\u300D\nfunction sv(R, k) { var x = R && R.v ? R.v[k] : ''; return x === undefined || x === null ? '' : String(x); }\nfunction parseKey(k) { var m = /^([^#]+)#(\\d+)$/.exec(String(k)); return m ? { full: m[1], n: parseInt(m[2], 10) } : null; }\n\n// 1/0 \u2194 \u5E03\u6797\uFF08slot \u88E1\u53EA\u6709\u5B57\u4E32\uFF09\nfunction isOn(R, k) { return sv(R, k) === '1'; }\n\n// \u2500\u2500 \u6587\u4EF6\uFF1A\u5F9E record \u89E3\u51FA\u4F86\u7684\u6B04\u4F4D \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction meOf(who, tokid) {\n  if (!tokid || tokid === 'none') return '';\n  var rows = rowsOf(who);\n  for (var i = 0; i < rows.length; i++) {\n    if (sv(rows[i], 'token_sha256') === tokid && !isOn(rows[i], 'revoked')) return sv(rows[i], 'login');\n  }\n  return '';\n}\n// prep \u5171\u7528\u7684\u8D77\u624B\u5F0F\uFF1A\u89E3\u6790\u8ACB\u6C42\u4FE1\u5C01\u3002\u8DEF\u5F91\u53C3\u6578\u7531\u6A4B\u4F9D\u8DEF\u7531\u8868\u5207\u597D\u653E\u5728 params\u3002\nfunction issueRidsOf(tenant, keys) { return uniq(keys).map(function (k) { return issueRid(tenant, k); }); }\nfunction batch2Out(ids) {\n  ids = uniq(ids || []);\n  if (ids.length > 200) throw new Error('\u4E00\u6B21\u6700\u591A\u8B80 200 \u7B46\uFF0C\u62FF\u5230 ' + ids.length);\n  return { success: true, branch: ids.length ? '1' : '0', nids: ids.length, ids: ids };\n}\n// \u7B2C\u4E00\u6BB5\u8B80\u7684\u7D50\u679C\uFF1Areads[0] \u662F\u8EAB\u5206\u67E5\u8A62\uFF08\u6709\u7684\u8A71\uFF09\u3002\u4EFB\u4F55\u4E00\u8B80\u5931\u6557\uFF08\u4E0D\u662F\u300C\u6C92\u6709\u8CC7\u6599\u300D\u800C\u662F KBDB \u56DE\u932F\uFF09\uFF1D\u6574\u500B\u8ACB\u6C42\u4E0D\u80FD\u4FE1\nfunction meIn(input) {\n  var P = input.prep, a = Array.isArray(input.reads) ? input.reads : [];\n  if (P && P.act) return actOk(P.act) && P.whon ? ownerNameOf(settingsOf(a[0]), P.act) : '';\n  return P && P.whon ? meOf(a[0], P.tokid) : '';\n}\n// \u65B7\u8A00\u9A57\u904E\u3001\u800C\u4E14\u662F Portal \u7684\u7BA1\u7406\u54E1\uFF08\u5BE6\u4F8B\u4E3B\u4EBA\uFF09\u624D\u7B97\uFF1B\u4F5C\u8005\u540D\u7531 ownerNameOf \u6C7A\u5B9A\nfunction actOk(A) { return !!(A && A.valid === true && A.role === 'admin'); }\n// \u79DF\u6236\u8A2D\u5B9A\uFF08ahub_setting\uFF0Ckey=signoff\uFF1Binkstone/Arcrun#328\uFF09\u3002\u6C92\u8A2D\uFF1D{owner_name:'', approvers:[]}\nfunction settingsOf(r) {\n  var R = null;\n  rowsOf(r).forEach(function (x) { if (!R && sv(x, 'key') === 'signoff') R = x; });     // \u65B0\u2192\u820A\uFF0C\u53D6\u6700\u65B0\u4E00\u7B46\n  return { R: R, owner_name: sv(R, 'owner_name'), approvers: approverList(sv(R, 'approvers')) };\n}\n// \u5BE6\u4F8B\u4E3B\u4EBA\u5F9E Portal \u5BEB\u5165\u6642\u7684\u7F72\u540D\uFF1A\u79DF\u6236\u8A2D\u5B9A\u7684 owner_name\uFF1B\u6C92\u8A2D\u5C31\u7528 Portal \u7684\u767B\u5165\u540D\uFF08\u4E0D\u518D\u5BEB\u6B7B Leo\uFF09\nfunction ownerNameOf(S, A) { return (S && S.owner_name) || (A && A.login) || ''; }\n// \u65B7\u8A00\u4E0D\u5408\u683C\u6642\u56DE\u4EC0\u9EBC\uFF1A\u9A57\u4E0D\u904E 401\u3001\u4E0D\u662F\u4E3B\u4EBA 403\uFF08\u5148\u9A57\u8EAB\u5206\u2014\u2014\u6C92\u901A\u904E\u7684\u4EBA\u4E0D\u8A72\u5F9E\u932F\u8AA4\u8A0A\u606F\u5F97\u77E5\u6771\u897F\u5B58\u4E0D\u5B58\u5728\uFF09\nfunction readsOf(input) { var a = Array.isArray(input.reads) ? input.reads : []; return a.slice(input.prep && input.prep.whon ? input.prep.whon : 0); }\nfunction issueRid(tenant, key) {\n  var p = parseKey(key);\n  if (!p || !tenant) throw new Error('issueRid \u9700\u8981 tenant \u8207\u5408\u6CD5\u7684\u7968\u9375');\n  return 'ahub~' + tenant + '~i~' + p.full.replace('/', '~') + '~' + p.n;\n}\nfunction approverList(v) {\n  var a = Array.isArray(v) ? v : String(v == null ? '' : v).split(',');\n  var seen = {}, out = [];\n  a.forEach(function (x) { x = String(x == null ? '' : x).trim(); var k = x.toLowerCase(); if (x && !seen[k]) { seen[k] = 1; out.push(x); } });\n  return out;\n}\nfunction claimDoc(R) {\n  return { rid: R.rid, key: sv(R, 'key'), station: sv(R, 'station'), session_url: sv(R, 'session_url'), state: sv(R, 'state') || 'doing',\n    blocked_on: sv(R, 'blocked_on'), claimed_at: sv(R, 'claimed_at'), updated_at: sv(R, 'updated_at') || sv(R, 'claimed_at'),\n    milestone: parseInt(sv(R, 'milestone'), 10) || 0 };\n}\n\nvar READS2_N = 0;\n\nvar P = input.prep, me = meIn(input);\nif (!me || P.early) return batch2Out([]);\nvar rs = readsOf(input);\nvar keys = rowsOf(rs[0]).concat(rowsOf(rs[1])).map(claimDoc).filter(function (c) { return !P.name || c.station === P.name; }).map(function (c) { return c.key; });\nreturn batch2Out(issueRidsOf(P.tenant, keys.slice(0, 200)));\n",
