function accountLabelOf(values) {
  const name = (values.display_name ?? "").trim();
  const email = (values.email ?? "").trim();
  if (name && email) return `${name}\uFF08${email}\uFF09`;
  return name || email || "\u9019\u500B\u5E33\u865F";
}
function toChatCards(cards, account, accountId) {
  return cards.map((c) => ({
    account,
    account_id: accountId,
    library: c.library,
    page_name: c.page_name,
    found_by: c.found_by,
    content: String(c.content ?? ""),
    location: c.location ?? null
  }));
}
portalDataRouter.post(
  "/portal/data/ask",
  (c) => run(c, async () => {
    const auth = await requirePortalUser(c);
    if (!auth.ok) return auth.res;
    const body = await c.req.json().catch(() => null);
    const question = typeof body?.question === "string" ? body.question.trim().slice(0, 500) : "";
    if (!question) return c.json({ error: "question \u5FC5\u586B" }, 400);
    const history = sanitizeHistory(body?.history);
    const q = normalizeCjkQuery(retrievalQuery(question, history));
    const libraries = parseLibraries(auth.user.values.libraries);
    const selfLabel = "\u672C\u5E33\u865F";
    const selfP = libraries.length === 0 ? Promise.resolve({ ok: false, detail: "\u9019\u500B\u5E33\u865F\u5C1A\u672A\u88AB\u6388\u6B0A\u4EFB\u4F55\u77E5\u8B58\u5EAB\uFF0C\u8ACB\u806F\u7D61\u7BA1\u7406\u54E1\u3002" }) : retrieveForLibraries(c.env, libraries, q).then(async (r) => r.ok ? { ok: true, cards: toChatCards(r.body.cards, selfLabel, "self") } : { ok: false, detail: `\u672C\u5E33\u865F\u77E5\u8B58\u5EAB\u8B80\u53D6\u5931\u6557\uFF08HTTP ${r.res.status}\uFF09` });
    const links = await listStoredLinks(c.env, auth.user.recordId).catch(() => []);
    const remoteP = links.map(
      (l) => callLinkedAccount(
        l.base_url,
        l.link_key,
        `/portal/link/retrieve?q=${encodeURIComponent(q)}`
      ).then((r) => ({ link: l, r }))
    );
    const [self, ...remotes] = await Promise.all([selfP, ...remoteP]);
    const perAccount = [];
    const accounts = [];
    if (self.ok) {
      perAccount.push(self.cards);
      accounts.push({ id: "self", label: selfLabel, ok: true, count: self.cards.length });
    } else {
      accounts.push({ id: "self", label: selfLabel, ok: false, count: 0, reason: "unavailable", detail: self.detail });
    }
    for (const { link, r } of remotes) {
      const label = link.label || link.remote_account || link.base_url;
      if (r.ok) {
        const cards2 = Array.isArray(r.body.cards) ? r.body.cards : [];
        perAccount.push(toChatCards(cards2, label, link.link_id));
        accounts.push({ id: link.link_id, label, ok: true, count: cards2.length });
      } else {
        accounts.push({ id: link.link_id, label, ok: false, count: 0, reason: r.reason, detail: r.detail });
      }
    }
    const merged = mergeCards(perAccount);
    const selfCards = merged.filter((cd) => cd.account_id === "self");
    const ov = await proofreadOverlay(c.env, auth.user.recordId, selfCards);
    const corrected = new Map(ov.cards.map((cd) => [`${cd.library}\u241F${cd.page_name}`, cd.content]));
    const cards = merged.map((cd) => cd.account_id === "self" ? { ...cd, content: corrected.get(`${cd.library}\u241F${cd.page_name}`) ?? cd.content } : cd);
    const publicCards = (cited) => cards.map((cd, i) => ({
      n: i + 1,
      account: cd.account,
      account_id: cd.account_id,
      library: cd.library,
      page_name: cd.page_name,
      found_by: cd.found_by,
      location: cd.location,
      // 點開卡片時先看得到內容（別的帳號的卡要登入那邊才讀得到整張，這裡給前 600 字）
      excerpt: cd.content.length > 600 ? `${cd.content.slice(0, 600)}\u2026` : cd.content,
      cited: cited.has(i + 1)
    }));
    const config = await readExtractAiConfig(c.env).catch(() => void 0);
    if (!config) return c.json({ error: "\u8B80\u4E0D\u5230\u9019\u53F0\u96F2\u7AEF\u7684 AI \u8A2D\u5B9A", code: "ai_config_unreadable", accounts, cards: publicCards(/* @__PURE__ */ new Set()) }, 502);
    const ans = await answerFromCards(c.env, knowledgeOwner(c.env), config, question, cards, history);
    if (!ans.ok) {
      return c.json({ error: `AI \u56DE\u7B54\u5931\u6557\uFF1A${ans.error}`, code: ans.code, accounts, cards: publicCards(/* @__PURE__ */ new Set()) }, 502);
    }
    return c.json({
      answer: ans.answer,
      model: ans.model,
      cards: publicCards(new Set(citedNumbers(ans.answer, cards.length))),
      accounts,
      probe: ov.probe,
      ...ov.unavailable ? { proofread_unavailable: true } : {}
    });
  })
);
